import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import ItemList from 'flarum/common/utils/ItemList';
import Hero from './Hero';
import { TagChips, TagGrid } from './TagGrid';
import LatestPanel from './LatestPanel';
import WidgetSlot from './WidgetSlot';
import Games from './Games';
import ComposeFab from './ComposeFab';
import { getPortal, loadPortal } from '../portalData';
import { has, isPhone, markPortal } from '../util';
import { fofSection } from '../widgets';

/**
 * The front page: the hero, the forum's sections, the latest discussions and
 * a sidebar.
 *
 * Extensions add to the sidebar through `sidebarItems()`, exactly as they add
 * to any of core's ItemLists, or to `WidgetSlot` to appear on the discussion
 * page as well:
 *
 *   extend(MastheadPortal.prototype, 'sidebarItems', (items) => items.add('mine', <Mine />, 50));
 */
export default class MastheadPortal extends Page {
  oninit(vnode) {
    super.oninit(vnode);
    this.bodyClass = 'App--masthead-portal';
    app.history.push('masthead.portal', app.forum.attribute('title'));
    app.setTitle('');
    app.setTitleCount(0);
    loadPortal();
  }
  view() {
    const data = getPortal();
    const phone = isPhone();
    return m("div", {
      className: "MastheadPortal"
    }, m("div", {
      className: "container"
    }, data ? m(Hero, {
      stories: data.hero,
      empty: data.heroEmpty,
      style: app.forum.attribute('mastheadHero') || 'overlay'
    }) : m("div", {
      className: "MastheadHero MastheadHero--loading",
      "aria-hidden": "true"
    }), has('flarum-tags') ? phone ? m(TagChips, null) : m(TagGrid, {
      limit: app.forum.attribute('mastheadTagCount') || 12
    }) : null, fofSection('top', 'MastheadFofSection--top'), m("div", {
      className: "MastheadColumns"
    }, m(LatestPanel, null), m("aside", {
      className: "MastheadSidebar"
    }, this.sidebarItems().toArray())), fofSection('bottom', 'MastheadFofSection--bottom')), phone ? m(ComposeFab, null) : null);
  }
  sidebarItems() {
    const items = new ItemList();
    const games = getPortal()?.games;

    // Nothing between seasons: an empty schedule on a front page reads as
    // broken (Picks' own leaderboard block hides when empty for the same reason).
    if (games && games.length) items.add('games', m(Games, {
      games: games
    }), 100);

    // The slot the discussion page shares: top posters, and whatever other
    // extensions put there.
    items.add('slot', m(WidgetSlot, {
      where: "portal"
    }), 50);

    // fof/forum-widgets-core's side areas: the portal has one sidebar, so its
    // start areas open and close it and its end area follows the slot.
    const startTop = fofSection('start_top', 'MastheadFofSection--side');
    const end = fofSection('end', 'MastheadFofSection--side');
    const startBottom = fofSection('start_bottom', 'MastheadFofSection--side');
    if (startTop) items.add('fofStartTop', startTop, 110);
    if (end) items.add('fofEnd', end, 40);
    if (startBottom) items.add('fofStartBottom', startBottom, 10);
    return items;
  }
}
markPortal(MastheadPortal);
flarum.reg.add('ernestdefoe-masthead', 'forum/components/Portal', MastheadPortal);